def descriptions_for(key):
 meanings={'question_id':'Stable source question identifier, retained across answer instances.','required':'Whether this field or check was required under the effective source policy; null means not established.','instance_path':'Source pointer identifying a repeatable answer instance.','answer_type':'Source form element type; determines how scalar, multi-value or file answers are represented.','reviewed_at':'UTC time the hit disposition was reviewed; null means no completed review is recorded.','first_seen_at':'UTC time this source first recorded the candidate, when known.','last_seen_at':'UTC time this source last recorded the candidate, when known.','matched_name':'Candidate subject name returned by screening, not a confirmed identity match.','list_name':'Screening list or dataset name actually returned for the candidate.','list_authority':'Authority publishing the screening list, when identified by the source.','source_record_reference':'Permitted native screening record identifier used to trace this candidate.','review_reason':'Recorded explanation for confirming or excluding this candidate.','chip_read':'Whether the NFC chip was successfully read; this alone does not prove authenticity.','passive_authentication':'Whether the chip data signature passed passive authentication.','active_authentication':'Whether active authentication passed the chip challenge-response check.','chip_authentication':'Whether cryptographic chip authentication passed.','data_integrity':'Whether the reported chip data-integrity checks passed.','certificate_valid':'Whether the relevant certificate passed the source validation checks.','protocol':'Reported chip authentication or communication protocol.','skipped_reason':'Explicit reason this check was skipped; do not infer a passing outcome.','signature_valid':'Whether the credential signature passed source validation.','assurance_level':'Assurance level stated by the credential issuer or verification source.','credential_type':'Type of verified digital credential.','known_share':'Evidenced fraction of the stated ownership denominator, 0 to 1; null if the denominator is unsupported.','unknown_share':'Unresolved fraction of the same ownership denominator, 0 to 1; null if unsupported.','ownership_basis':'Whether coverage refers to economic equity, voting rights, mixed interests or an unknown basis.','unresolved_subject_ids':'Related subjects whose identity or ownership chains remain unresolved.','authorized_quantity':'Authorized number of shares in this class; null for unquantified or unknown amounts.','unlimited':'Whether the governing articles explicitly authorize an unlimited number of this share class.','issued_quantity':'Number of this class reported as issued, not inferred from authorized capital.','votes_per_share':'Number of votes per share in this class, represented as a decimal string.','voting_rights':'Source wording describing voting rights attached to this share class.','dividend_rights':'Source wording describing dividend rights and priorities.','liquidation_rights':'Source wording describing distribution priorities on liquidation.','redemption_terms':'Source wording describing redemption rights or obligations.','status':'State of this specific result; separate from entity legal status and lending decisions.','reason':'Explicit explanation code when no complete usable value is available.','outcome':'Verification/compliance result, not a lending decision.','items':'All authorized observations in this section, including distinct source observations.','coverage':'Actual requested and completed source scope with limitations.','provenance':'Exact source, time, basis and evidence for this observation.','missing_fields':'Every absent or null required fact is explained by a pointer and a missing-data reason.','sources':'Actual consulted source snapshots and scope.','ownership_resolution':'Whether ownership chains and the stated denominator are fully evidenced.','documents':'Source files accessible through existing document endpoints with authorization rechecked.','evidence':'Exact evidence records and source-document locations.','field_evidence':'Field-specific provenance for values that differ from the item-level source.','reported_hit_count':'Source-reported number of candidate matches, not a count of confirmed sanctions.','disposition':'Review state; unreviewed candidates are not confirmed matches.','review_reason':'Reason supporting the documented match disposition.','definition_version':'Version of the normalized verification field definitions.','supplemental_facts':'Allowlisted source-specific underwriting facts with names, types, meaning and provenance.'}
 return meanings.get(key,key.replace('_',' ').capitalize()+'. Preserve the source meaning; null or unknown does not establish a negative or a verified result.')


def empty_assessment(borrower_id,as_of,borrower_type='business'):
 result={'id':'verify_assessment_synthetic','borrower_id':borrower_id,'subject_id':'biz_synthetic' if borrower_type=='business' else 'person_synthetic','definition_version':VERSION,'as_of':as_of,'status':'unavailable','outcome':'not_performed','summary':'Synthetic example: no verification source results are included.','sources':[],'ownership_resolution':{'status':'unavailable' if borrower_type=='business' else 'not_applicable','reason':'No ownership evidence included.' if borrower_type=='business' else 'Individual borrower; ownership is not required for this example.','unresolved_subject_ids':[],'ownership_basis':'unknown','known_share':None,'unknown_share':None},'documents':[]}
 for key in SECTIONS:
  result[key]={'status':'unavailable','reason':'not_requested','explanation':'No result included in this synthetic example.','coverage':{'status':'not_requested','requested_scopes':[],'completed_scopes':[],'limitations':['No completed check is claimed.']},'items':[]}
 return result


def semantic_errors(a):
 """Cross-field invariants for adapters and API conformance tests."""
 from decimal import Decimal
 errors=[]
 source_ids={x['id'] for x in a['sources']}
 if len(source_ids)!=len(a['sources']):errors.append('Verification source IDs must be unique.')
 def coverage_errors(c):
  if not set(c['completed_scopes'])<=set(c['requested_scopes']):errors.append('Completed scope was not requested.')
  if c['status']=='complete' and (not c['requested_scopes'] or set(c['completed_scopes'])!=set(c['requested_scopes'])):errors.append('Complete coverage requires an explicit completed requested scope.')
 for source in a['sources']:coverage_errors(source['coverage'])
 for doc in a['documents']:
  if doc['source_id'] not in source_ids:errors.append('Document references unknown source.')
 ids=[v['id'] for key in SECTIONS for v in a[key]['items']]
 if len(set(ids))!=len(ids):errors.append('Verification item IDs must be unique.')
 for key in SECTIONS:
  sec=a[key]
  for c in [sec['coverage'],*[i['coverage'] for i in sec['items'] if 'coverage' in i]]:
   coverage_errors(c)
  for item in sec['items']:
   if item['provenance']['source_id'] not in source_ids:errors.append('Unknown verification source.')
   if not item['provenance']['evidence']:errors.append('Observation lacks evidence.')
   missing={m['path'] for m in item['missing_fields']}
   for k,v in item.items():
    if v is None and '/'+k not in missing:errors.append('Null observation field lacks a missing-data reason: '+k)
 for x in a['ownership']['items']:
  for low,high in [('economic_share_min','economic_share_max'),('voting_share_min','voting_share_max')]:
   if x[low] is not None and x[high] is not None and Decimal(x[low])>Decimal(x[high]):errors.append('Invalid ownership range.')
  if x['effective_share'] is not None and (not x['chain_complete'] or len(x['chain_subject_ids'])<2):errors.append('Indirect ownership requires a supported complete chain.')
 for x in a['screenings']['items']:
  if x['returned_hit_count']!=len(x['hits']):errors.append('Screening hit counts disagree.')
  if x['reported_hit_count'] is not None and x['reported_hit_count']<x['returned_hit_count']:errors.append('Returned hits exceed provider total.')
  if x['result']=='confirmed_match' and not any(h['disposition']=='confirmed' for h in x['hits']):errors.append('Confirmed match requires a confirmed hit.')
  if x['result']=='no_match' and (x['hits'] or x['state']!='completed' or x['coverage']['status']!='complete'):errors.append('No-match requires a completed search with complete scoped coverage and no hits.')
  for hit in x['hits']:
   if hit['disposition'] in ['confirmed','false_positive'] and (not hit['reviewed_at'] or not hit['review_reason']):errors.append('A resolved screening hit requires review provenance.')
 for x in a['field_comparisons']['items']:
  if x['result']=='not_submitted' and (x['provided'] is not None or x['normalized_provided'] is not None):errors.append('Not-submitted comparison cannot contain submitted data.')
 for x in a['checks']['items']:
  if not set(x['item_ids'])<=set(ids):errors.append('Verification check references an unknown observation.')
 def scores(v):
  if isinstance(v,dict):
   if {'value','scale_min','scale_max','direction','method'}<=set(v):
    lo,hi,value=v['scale_min'],v['scale_max'],v['value']
    if lo is not None and hi is not None and lo>=hi:errors.append('Invalid provider score scale.')
    if value is not None and ((lo is not None and value<lo) or (hi is not None and value>hi)):errors.append('Provider score is outside its stated scale.')
   for value in v.values():scores(value)
  elif isinstance(v,list):
   for value in v:scores(value)
 scores(a)
 resolution=a['ownership_resolution']
 if resolution['known_share'] is not None and resolution['unknown_share'] is not None and Decimal(resolution['known_share'])+Decimal(resolution['unknown_share'])!=1:errors.append('Ownership coverage fractions do not reconcile.')
 if resolution['status']=='complete' and (resolution['unresolved_subject_ids'] or resolution['ownership_basis'] in ['unknown','mixed'] or (resolution['unknown_share'] is None or Decimal(resolution['unknown_share'])!=0) or any(not x['chain_complete'] for x in a['ownership']['items'])):errors.append('Complete ownership requires resolved chains and a known denominator.')
 for x in a['relationships']['items']:
  if x['verification_state']=='skipped' and not x['skip_reason']:errors.append('Skipped verification requires a reason.')
 if a['outcome']=='passed' and (not a['checks']['items'] or any(x['verification_required'] and x['verification_state']!='completed' for x in a['relationships']['items']) or any(x['required'] and x['affects_outcome'] and x['result']!='matched' for x in a['field_comparisons']['items'])):errors.append('Missing required checks or unresolved comparisons cannot become a pass.')
 if a['outcome']=='passed' and (a['status']!='complete' or any(x['required'] and x['outcome']!='passed' for x in a['checks']['items']) or any(x['result'] in ['potential_match','inconclusive'] for x in a['screenings']['items'])):errors.append('Unresolved required verification cannot become a pass.')
 return errors
